"""Recursive-descent evaluator for integer/float arithmetic expressions.

Grammar (lowest precedence first)::

    expr   := term (('+' | '-') term)*
    term   := unary (('*' | '/' | '//' | '%') unary)*
    unary  := ('+' | '-') unary | power
    power  := atom ['**' unary]
    atom   := INTEGER | '(' expr ')'

``unary`` binds looser than ``**`` so ``-2 ** 2 == -4`` while ``(-2) ** 2 == 4``.
``**`` is right-associative because its right operand is itself a ``unary``;
every other binary operator is left-associative.

Standard library only, and no eval/exec/ast/compile: the parser below is hand
written.
"""

__all__ = ["evaluate"]

# Multi-character operators must be tried before their single-character
# prefixes, otherwise "//" would tokenize as two "/" and "**" as two "*".
_OPERATORS = ("**", "//", "+", "-", "*", "/", "%", "(", ")")

_DIGITS = "0123456789"


class _Token:
    """A single lexical token: a kind, its text and its source offset."""

    __slots__ = ("kind", "text", "pos")

    def __init__(self, kind, text, pos):
        self.kind = kind  # "int", "op" or "end"
        self.text = text
        self.pos = pos

    def __repr__(self):  # pragma: no cover - debugging aid only
        return "_Token(%r, %r, %r)" % (self.kind, self.text, self.pos)


def _tokenize(text):
    """Turn *text* into a list of tokens terminated by an "end" token.

    Raises ValueError on any character the grammar does not accept.
    """
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]

        # Whitespace between tokens is insignificant.
        if ch.isspace():
            i += 1
            continue

        if ch in _DIGITS:
            start = i
            while i < n and text[i] in _DIGITS:
                i += 1
            # A digit run must not be glued to another operand-ish character:
            # "1.5", "1e5" and "1_000" are all rejected here rather than
            # silently truncated to "1".
            if i < n and (text[i] == "." or text[i] == "_" or text[i].isalnum()):
                raise ValueError(
                    "invalid numeric literal at position %d: only decimal "
                    "integers are supported" % start
                )
            tokens.append(_Token("int", text[start:i], start))
            continue

        for op in _OPERATORS:
            if text.startswith(op, i):
                tokens.append(_Token("op", op, i))
                i += len(op)
                break
        else:
            raise ValueError("unexpected character %r at position %d" % (ch, i))

    tokens.append(_Token("end", "", n))
    return tokens


class _Parser:
    """Recursive-descent parser that evaluates as it parses."""

    def __init__(self, tokens):
        self._tokens = tokens
        self._index = 0

    # -- token helpers -------------------------------------------------

    @property
    def _current(self):
        return self._tokens[self._index]

    def _at_op(self, *ops):
        token = self._current
        return token.kind == "op" and token.text in ops

    def _advance(self):
        token = self._tokens[self._index]
        self._index += 1
        return token

    def _describe(self, token):
        if token.kind == "end":
            return "unexpected end of expression"
        return "unexpected %r at position %d" % (token.text, token.pos)

    # -- grammar rules -------------------------------------------------

    def parse(self):
        """Parse a whole expression and require that the input is consumed."""
        value = self.expr()
        token = self._current
        if token.kind != "end":
            # Covers trailing junk such as "1 + 2)" and adjacent operands
            # such as "2 3".
            raise ValueError(self._describe(token))
        return value

    def expr(self):
        value = self.term()
        while self._at_op("+", "-"):
            op = self._advance().text
            right = self.term()
            value = value + right if op == "+" else value - right
        return value

    def term(self):
        value = self.unary()
        while self._at_op("*", "/", "//", "%"):
            token = self._advance()
            right = self.unary()
            value = self._apply_multiplicative(token.text, value, right)
        return value

    @staticmethod
    def _apply_multiplicative(op, left, right):
        if op == "*":
            return left * right
        if op == "/":
            if right == 0:
                raise ZeroDivisionError("division by zero")
            # True division always yields a float, even for exact int results.
            return left / right
        if op == "//":
            if right == 0:
                raise ZeroDivisionError("integer division or modulo by zero")
            return left // right
        # op == "%"
        if right == 0:
            raise ZeroDivisionError("integer division or modulo by zero")
        return left % right

    def unary(self):
        if self._at_op("+", "-"):
            op = self._advance().text
            # Recurse so that unary operators are repeatable: "--3" == 3.
            operand = self.unary()
            return +operand if op == "+" else -operand
        return self.power()

    def power(self):
        base = self.atom()
        if self._at_op("**"):
            self._advance()
            # Right operand is a `unary`, which makes "**" right-associative
            # and lets "2 ** -1" parse (and then fail the exponent check).
            exponent = self.unary()
            if exponent < 0:
                raise ValueError("negative exponents are not supported")
            return base ** exponent
        return base

    def atom(self):
        token = self._current
        if token.kind == "int":
            self._advance()
            return int(token.text)
        if token.kind == "op" and token.text == "(":
            self._advance()
            value = self.expr()  # rejects "()" -- expr needs an operand
            if not self._at_op(")"):
                raise ValueError(
                    "unbalanced parenthesis: %s" % self._describe(self._current)
                )
            self._advance()
            return value
        # Missing operand: "2 +", "", "* 3", "()" and friends land here.
        raise ValueError(self._describe(token))


def evaluate(text):
    """Evaluate the arithmetic expression *text* and return an int or float.

    Raises ValueError for input the grammar does not accept and
    ZeroDivisionError for division or modulo by zero.
    """
    if not isinstance(text, str):
        raise TypeError("expression must be a string, not %s" % type(text).__name__)
    if not text.strip():
        raise ValueError("empty expression")
    return _Parser(_tokenize(text)).parse()

