"""Differential fuzz: iterative solution vs. the recursive reference parser.

Both implement the same grammar independently, so any disagreement on value,
value type, or exception type is a bug in one of them.
"""

import random
import sys

sys.path.insert(0, "/workspace/proj2")

import reference_recursive
import solution

TOKENS = [
    "0", "1", "2", "3", "7", "10",
    "+", "-", "*", "/", "//", "%", "**",
    "(", ")", " ",
]


def outcome(func, expr):
    try:
        value = func(expr)
    except ValueError:
        return ("ValueError",)
    except ZeroDivisionError:
        return ("ZeroDivisionError",)
    except RecursionError:
        return ("RecursionError",)
    except Exception as err:  # noqa: BLE001
        return ("OTHER", type(err).__name__, str(err))
    return ("value", type(value).__name__, value)


random.seed(20240605)

mismatches = 0
checked = 0
interesting = 0  # expressions that actually evaluated to a number

for _ in range(200000):
    length = random.randint(1, 9)
    parts = [random.choice(TOKENS) for _ in range(length)]
    expr = "".join(parts)
    # Guard against astronomically large powers that would hang the process.
    if expr.count("**") > 2:
        continue
    checked += 1

    got = outcome(solution.evaluate, expr)
    want = outcome(reference_recursive.evaluate, expr)
    if got[0] == "value":
        interesting += 1
    if got != want:
        mismatches += 1
        if mismatches <= 25:
            print("MISMATCH %r: solution=%r reference=%r" % (expr, got, want))

print("checked=%d evaluated_ok=%d mismatches=%d" % (checked, interesting, mismatches))

